  str_n5_mission_title_14 = "Um Inimigo Formidável-N10",
  str_n5_mission_title_15 = "De Frente-N11",
  str_n5_mission_title_16 = "Esperança-ST5",
  str_n5_mission_desc_1 = "Enquanto estava a bordo da Colossus, você recebeu uma mensagem inesperada da Subcidade Illumina.",
  str_n5_mission_desc_2 = "Você chega na Subcidade 24 e se encontra com o oficial de lá.",
  str_n5_mission_desc_3 = "Como incorporaram novos membros em sua força-tarefa, o Oficial Brent está preocupado com seu desempenho.",
  str_n5_mission_desc_4 = "Você se junta à equipe de transporte sem problemas, mas antes de começar sua missão, Brent te informa que a camaradagem é vital para promover a cooperação dentro da equipe.",
  str_n5_mission_desc_5 = "Entre a tempestade de areia e os Eclipsitas, a equipe de transporte parece incapaz de continuar sua missão de transporte, mas Ansia se recusa a desistir.",
  str_n5_mission_desc_6 = "O exército Eclipsita ataca a Subcidade 24, mas não há forças presentes capazes de defendê-la.",
  str_n5_mission_desc_7 = "Conforme o gigante Eclipsita voador ataca, atirar nele parece ser a melhor opção!",
  str_n5_mission_desc_8 = "Ao encarar os Eclipsitas mais poderosos, há sempre aqueles que resistem com bravura incomparável.",
  str_n5_mission_desc_9 = "No cruel campo de batalha, a linha é tênue entre vitória e derrota.",
  str_n5_mission_desc_10 = "Por ter herdado o desejo da resistência, você deve encarar agora o inimigo mais ameaçador uma vez mais…",
  str_n5_mission_desc_11 = "O contra-ataque ainda não acabou. Você deve levar notícias da sua vitória para seus companheiros!",
  str_n5_mission_desc_12 = "A defesa da Subcidade 24 é só uma parte desta batalha. Agora fique de olho em outro alvo.",
  str_n5_mission_desc_13 = "A Subcidade 23 posicionada na linha defensiva enfrenta ataques contínuos do exército de Eclipsitas. Como a sua chegada mudará a situação?",
  str_n5_mission_desc_14 = "Após Barton aparecer com suas tropas, você recapturou a retaguarda com sucesso, mas será que tudo está ocorrendo sem problemas como parece?",
  str_n5_mission_desc_15 = "Ao encarar um inimigo poderoso mais uma vez, nenhum de vocês está pronto para recuar. Essa batalha não só servirá como o primeiro passo para a vitória, como precisa ser vencida em homenagem aos heróis caídos que vieram antes de vocês!",
  str_n5_mission_desc_16 = "Após voltar para a Subcidade 24, todos decidem qual tipo de futuro querem buscar.",
  str_n5_mission_desc_long_1 = "Você se depara com um problema técnico enquanto tenta entrar em contato com Illumina. Após ajustar o dispositivo de comunicação, recebe uma mensagem inesperada da Subcidade 24 pedindo ajuda. Convencido pelo raciocínio de Vice, você finalmente decide ir para a Subcidade 24.",
  str_n5_mission_desc_long_2 = "Você pousa na estação de transporte e é lá que conhece o Brent. Após escutar suas intenções, o oficial, que lidera a força-tarefa da Subcidade 24, decide que você deve se juntar às suas forças.",
  str_n5_mission_desc_long_3 = "Incerto do seu preparo físico e habilidades de comando, Oficial Brent exige que você demonstre imediatamente a ele suas habilidades contra Eclipsitas. No momento em que está em perigo, cercado por Eclipsitas, um soldado chamado Gram aparece.",
  str_n5_mission_desc_long_4 = "Ansia, líder da equipe de transporte, solicita ajuda, esperando que você possa ajudar os outros dois membros da equipe que estão discutindo a resolver suas diferenças. Após ouvir suas histórias, você descobre que o verdadeiro “problema” da equipe de transporte é a Ansia.",
  str_n5_mission_desc_long_5 = "Ansia, líder da equipe de transporte, solicita que você use a Colossus para transportar bens da Subcidade 23. Durante o curto período que teve para preparação, você descobre que o poderoso talento secreto de Gram é culinária.",
  str_n5_mission_desc_long_6 = "Contra o exército Eclipsita, Brent permanece calmo diante do perigo. Ele ordena que a Colossus seja usada para evacuar alguns civis, e divide as forças disponíveis da cidade em duas unidades. Uma unidade está encarregada de lançar um ataque no líder Eclipsita, enquanto as forças restantes são ordenadas a ajudar nos esforços de bombardeio para lidar com os Eclipsitas que atacam a cidade.",
  str_n5_mission_desc_long_7 = "O oficial veterano da Subcidade 24 acerta, com sucesso, o líder Eclipsita. Você vai até o local em que ele caiu, de acordo com o plano atual, e se prepara para acabar com ele. Porém, a imprevisibilidade é a única constante no campo de batalha, e um estrondo ensurdecedor ecoa no ar.",
  str_n5_mission_desc_long_8 = "Conforme o Eclipsita gigante ataca a Subcidade 24, Brent rapidamente formula um plano de batalha e decide levar um pequeno esquadrão para encará-lo. Eles decidem usar o terreno e armadilhas de mina na estação para impedir o poderoso Eclipsita.",
  str_n5_mission_desc_long_9 = "Após escapar por sorte da explosão, você ansiosamente corre de volta para a estação. Porém, o líder Eclipsita caído, que você imaginava ter sido obliterado pela explosão, surge mais uma vez e ataca Brent",
  str_n5_mission_desc_long_10 = "Brent sofre um golpe direto de um inimigo Eclipsita, mas seu espírito se mantém forte contra o medo da morte. Vendo sua rápida chegada, ele acredita que você pode derrotar o Eclipsita e defender a Subcidade.",
  str_n5_mission_desc_long_11 = "Graças à sua perseverança inabalável, a defesa da Subcidade 24 está finalmente garantida. Gram decide levar a notícia da sua vitória para seus companheiros de anos passados e se despedir.",
  str_n5_mission_desc_long_12 = "Após deduzir que o alvo dos Eclipsitas é de fato a carga transportada pela equipe de transporte, você decide escoltar esses importantes suprimentos para seu destino final: Subcidade 23 na Linha Dunafogo, até a vanguarda contra o ataque Eclipsita.",
  str_n5_mission_desc_long_13 = "Após usar a Colossus e sua habilidade psíquica para verificar a situação ao longo da linha defensiva, Gram, que possui anos de experiência de combate, decide lançar uma incursão na direção dos Eclipsitas para acabar o cerco da Subcidade 23. E então, você, de forma resoluta, decide… pular da Colossus e saltar de paraquedas atrás da linha inimiga!",
  str_n5_mission_desc_long_14 = "Embora o jogo pareça ter virado, um mau presságio volta a reinar quando o líder Eclipsita aparece novamente.",
  str_n5_mission_desc_long_15 = "Encarando esse formidável inimigo mais uma vez, todos estão totalmente preparados para a batalha. Compelidos pela raiva e determinação, vocês aniquilam o inimigo, marcando a vitória na defesa da Subcidade 23 e grande sucesso na salvaguarda da linha defensiva.",
  str_n5_mission_desc_long_16 = "Após a Vanguarda Dunafogo declarar sua vitória defensiva total, você volta para a Subcidade 24. No meio da quietude da euforia pós-batalha, todos decidem sobre os respectivos caminhos que desejam trilhar no futuro: viver pelos seus ideais e lutar lado a lado, com e para seus compatriotas.",
  str_n5_battlefield_refreshed = "Rein. Campo de Batalha",
  str_n5_record_militaryexploit = "O Mérito obtido será salvo.",
  str_n5_today_max_militaryexploit = "Dentre os quatro campos de batalha a seguir, apenas o campo no qual conseguiu o maior Mérito no dia será contabilizado para seu Mérito Total."
}
